package ru.neverland.townyspecialization.production;

import java.io.File;
import java.util.*;
import java.util.concurrent.*;
import java.util.function.Supplier;
import org.bukkit.entity.Player;
import org.bukkit.plugin.java.JavaPlugin;
import org.bukkit.configuration.file.YamlConfiguration;
import com.palmergames.bukkit.towny.TownyAPI;
import ru.neverland.core.*;
import ru.neverland.townyspecialization.service.SpecializationService;
import static ru.neverland.townyspecialization.production.ProductionRepository.*;

/** Folia player authorization surrounds asynchronous durable operations; no SQL is awaited by a tick. */
public final class ProductionService {
    public record Actor(UUID town,String profile,String name){}
    private final JavaPlugin plugin;private final SpecializationService specialization;private final ProductionRepository repo;
    private final ProfileGoodsProvider goods;
    public ProfileGoodsProvider goods(){return goods;}
    private final ProductionAudit audit;private final org.bukkit.scheduler.BukkitTask auditTask;private CompletableFuture<Void> stopped;
    private volatile ProductionCatalog catalog;private volatile String issue="Раздел загружается";private volatile boolean closed;
    private final Map<UUID,CompletableFuture<?>> active=new HashMap<>();private final Set<CompletableFuture<?>> owners=ConcurrentHashMap.newKeySet();
    public ProductionService(JavaPlugin plugin,SpecializationService specialization){this.plugin=plugin;this.specialization=specialization;repo=new ProductionRepository(plugin.getDataFolder().toPath().resolve("production.sqlite"));audit=new ProductionAudit(repo,row->AuditTrail.record(plugin,row),plugin.getLogger()::warning);auditTask=SuiteScheduler.get().runTaskTimer(plugin,()->{if(repo.available())audit.flush();},100,100);repo.ready().whenComplete((v,e)->{if(e!=null)plugin.getLogger().warning("Производственный каталог недоступен; прежняя специализация сохраняется: "+e.getMessage());});goods=new ProfileGoodsProvider(plugin,this);reload();}
    public ProductionRepository repository(){return repo;}public ProductionCatalog catalog(){if(catalog==null)throw new IllegalStateException(issue);return catalog;}public String issue(){return issue;}
    public void reload(){try{File file=new File(plugin.getDataFolder(),"production.yml");if(!file.isFile())plugin.saveResource("production.yml",false);var y=new YamlConfiguration();y.load(file);var next=ProductionCatalog.load(y);for(var p:next.products().values()){var icon=org.bukkit.Material.matchMaterial(p.icon());if(icon==null||!icon.isItem())throw new IllegalArgumentException("Неверная иконка партии");for(String material:p.materials().keySet()){var m=org.bukkit.Material.matchMaterial(material);if(m==null||!m.isItem()||m.isAir())throw new IllegalArgumentException("Материал партии не является предметом: "+material);}}catalog=next;issue="";}catch(Exception e){catalog=null;issue="Настройки производственных партий требуют проверки";plugin.getLogger().warning(issue+": "+e.getMessage());}}
    public UUID city(Player p){try(var guard=SuiteState.guard()){if(!plugin.isEnabled()||closed||SuiteState.frozen(plugin.getName())||!p.hasPermission("neverlandtownyspecialization.use"))throw new IllegalArgumentException("Производственный каталог временно недоступен");var town=specialization.town(p);if(town==null)throw new IllegalArgumentException("Для каталога нужен свой город");return town.getUUID();}}
    public Actor authorize(Player p,UUID expected,String required,boolean producing){try(var guard=SuiteState.guard()){
        UUID id=city(p);if(!id.equals(expected))throw new IllegalArgumentException("Вы перешли в другой город; действие остановлено");var town=TownyAPI.getInstance().getTown(id);var resident=TownyAPI.getInstance().getResident(p);if(town==null||resident==null||!town.isMayor(resident))throw new IllegalArgumentException("Распоряжаться производственными партиями может мэр своего города");
        var snapshot=specialization.specialization(id).orElseThrow(()->new IllegalStateException("Направление города ещё не проверено"));String profile=snapshot.state().specialization();if(required!=null&&!required.equals(profile))throw new IllegalArgumentException("Городу нужно направление: "+profileTitle(required));
        if(producing&&(snapshot.paused()||snapshot.uniqueLevel()<3))throw new IllegalArgumentException("Для новой партии нужно работающее уникальное здание направления III уровня или выше");return new Actor(id,profile,p.getName());
    }}
    public String profileTitle(String id){var p=specialization.settings().profiles().get(id);return p==null?"Направление не выбрано":p.name();}
    private void newWork(){var c=catalog();if(!c.enabled())throw new IllegalArgumentException("Новые партии и проекты отключены; сохранённые можно сверить или отменить");}
    @SuppressWarnings("unchecked")private <T>CompletionStage<T> external(String method,Class<?>[] types,Object...args){try{if(closed)throw new IllegalStateException("Каталог останавливается");var link=ApiServices.connect("NeverLandTownyContracts","ru.neverland.mintcontracts.api.ServerMaterialsApi",1,method,"cooperativeReady");if(!link.ready()||!Boolean.TRUE.equals(link.invoke("cooperativeReady",new Class<?>[0])))throw new IllegalStateException("Склад материалов временно недоступен; партии не изменены");Object value=link.invoke(method,types,args);if(!(value instanceof CompletionStage<?> stage))throw new IllegalStateException("Несовместимый ответ склада");return(CompletionStage<T>)stage;}catch(Exception|LinkageError e){return CompletableFuture.failedFuture(e);}}
    private CompletionStage<Map<String,Object>> source(Batch b){return external("cooperativeProject",new Class<?>[]{String.class},b.contract());}
    private CompletionStage<Map<String,Object>> plan(Batch b){return external("cooperativePlan",new Class<?>[]{String.class,String.class,String.class,String.class,String.class,long.class,Map.class,String.class},b.contract(),b.label(),"CITY",b.town().toString(),b.unlock(),1L,b.materials(),b.actor());}
    private CompletionStage<Map<String,Object>> finish(Batch b,boolean cancel,String actor){return external("cooperativeFinish",new Class<?>[]{String.class,boolean.class,String.class,String.class},b.contract(),cancel,actor,cancel?"Отмена производственной партии "+b.id():"Материалы обеспеченной производственной партии "+b.id());}
    private <T>CompletionStage<T> owner(Player p,Supplier<CompletionStage<T>> action){var result=new CompletableFuture<T>();if(closed||!plugin.isEnabled())return CompletableFuture.failedFuture(new IllegalStateException("Каталог останавливается; сохранённые операции доступны после запуска"));owners.add(result);result.whenComplete((v,e)->owners.remove(result));try{var task=SuiteScheduler.entityLater(plugin,p,()->{try{if(closed||!p.isOnline())throw new IllegalStateException("Игрок вышел; сохранённая операция доступна мэру позже");action.get().whenComplete((v,e)->{if(e==null)result.complete(v);else result.completeExceptionally(e);});}catch(Throwable e){result.completeExceptionally(e);}},()->result.completeExceptionally(new IllegalStateException("Игрок вышел; ресурсы сохранены")),1);if(task.isCancelled())result.completeExceptionally(new IllegalStateException("Каталог останавливается"));}catch(Throwable e){result.completeExceptionally(e);}return result;}
    private <T>CompletionStage<T> serial(UUID id,Supplier<CompletionStage<T>> work){try(var guard=SuiteState.guard()){if(closed)throw new IllegalStateException("Каталог останавливается");if(active.containsKey(id))throw new IllegalArgumentException("Операция уже сохраняется. Дождитесь результата");var result=new CompletableFuture<T>();active.put(id,result);try{work.get().whenComplete((v,e)->{try(var done=SuiteState.guard()){active.remove(id,result);}if(e==null)result.complete(v);else result.completeExceptionally(e);});}catch(Throwable e){active.remove(id);result.completeExceptionally(e);}return result;}}
    public CompletionStage<Batch> create(Player p,UUID request,UUID town,ProductionCatalog.Product product,int amount,ProductionCatalog quoted){
        return serial(request,()->{newWork();if(catalog()!=quoted||!quoted.products().containsValue(product))throw new IllegalArgumentException("Рецепты изменились; проверьте смету заново");authorize(p,town,product.profile(),true);
            return owner(p,()->{var actor=authorize(p,town,product.profile(),true);newWork();return repo.createBatch(request,town,product,amount,actor.name(),quoted.limits());}).thenCompose(b->owner(p,()->{authorize(p,town,product.profile(),true);return source(b).thenCompose(proof->ProductionRepository.validateSource(b,proof).equals("MISSING")?plan(b):CompletableFuture.completedFuture(proof));})).thenCompose(proof->owner(p,()->{var actor=authorize(p,town,product.profile(),false);return repo.acknowledge(request,proof,actor.name());}));
        });
    }
    public CompletionStage<Batch> resolve(Player p,UUID id,String action){
        return serial(id,()->repo.batch(id).thenCompose(b->{if(b==null)return CompletableFuture.failedFuture(new IllegalArgumentException("Партия не найдена"));return owner(p,()->{var actor=authorize(p,b.town(),action.equals("finish")?b.profile():null,action.equals("finish"));if(!Set.of("sync","finish","cancel").contains(action))throw new IllegalArgumentException("Неизвестное действие партии");if(Set.of("ISSUED","CANCELLED").contains(b.state())){if(action.equals("cancel")&&b.state().equals("ISSUED")||action.equals("finish")&&b.state().equals("CANCELLED"))throw new IllegalArgumentException("Завершённый выпуск или отмену нельзя обратить");return CompletableFuture.completedFuture(b);}
            return source(b).thenCompose(proof->settleSource(p,b,action,proof,false));
        });}));
    }
    private CompletionStage<Batch> settleSource(Player p,Batch b,String action,Map<String,Object> proof,boolean justPlanned){return owner(p,()->{
        var live=authorize(p,b.town(),action.equals("finish")?b.profile():null,action.equals("finish"));String state=ProductionRepository.validateSource(b,proof);
        if(Set.of("COMPLETED","CANCELLED").contains(state))return repo.acknowledge(b.id(),proof,live.name());
        if(state.equals("MISSING")){if(justPlanned)throw new IllegalStateException("Склад не подтвердил создание сметы; повторите сверку позже");return plan(b).thenCompose(planned->settleSource(p,b,action,planned,true));}
        if(action.equals("sync"))return repo.acknowledge(b.id(),proof,live.name());
        boolean cancel=action.equals("cancel");return repo.mark(b.id(),cancel,live.name()).thenCompose(marked->owner(p,()->{var verified=authorize(p,b.town(),cancel?null:b.profile(),!cancel);return finish(marked,cancel,verified.name());})).thenCompose(receipt->owner(p,()->{var verified=authorize(p,b.town(),null,false);return repo.acknowledge(b.id(),receipt,verified.name());}));
    });}
    @SuppressWarnings("unchecked")public List<Map<String,Object>> orders(Player p){city(p);try{var c=ApiServices.connect("NeverLandTownyContracts","ru.neverland.mintcontracts.api.ServerMaterialsApi",1,"cooperativeOrders");if(!c.ready())throw new IllegalStateException("Заказы недоступны");return(List<Map<String,Object>>)c.invoke("cooperativeOrders",new Class<?>[]{Player.class},p);}catch(ReflectiveOperationException e){throw new IllegalStateException("Заказы недоступны",e);}}
    public CompletionStage<Void> deliver(Player p,UUID order,Batch b){if(!city(p).equals(b.town()))throw new IllegalArgumentException("Это партия другого города");return external("cooperativeDeliver",new Class<?>[]{Player.class,UUID.class,String.class},p,order,b.contract());}
    public CompletionStage<Map<String,Object>> materials(Batch b){return source(b);}
    public CompletionStage<JointView> createProject(Player p,UUID id,UUID town,ProductionCatalog.Joint goal,ProductionCatalog quoted){return serial(id,()->{newWork();if(catalog()!=quoted||!quoted.projects().containsValue(goal))throw new IllegalArgumentException("Условия изменились; откройте подтверждение заново");authorize(p,town,null,false);return owner(p,()->{var actor=authorize(p,town,null,false);newWork();return repo.createProject(id,town,goal,quoted.products(),actor.name(),quoted.limits());});});}
    public CompletionStage<JointView> contribute(Player p,UUID receipt,UUID project,UUID town,String product,int amount){return serial(receipt,()->{authorize(p,town,null,false);return repo.joint(project).thenCompose(view->owner(p,()->{var actor=authorize(p,town,view.project().profiles().get(product),false);return repo.contribute(receipt,project,town,actor.profile(),product,amount,actor.name());}));});}
    public CompletionStage<JointView> finishProject(Player p,UUID id,boolean cancel){return serial(id,()->repo.joint(id).thenCompose(view->owner(p,()->{var actor=authorize(p,view.project().owner(),null,false);return repo.finishProject(id,actor.town(),cancel,actor.name(),cancel?"Мэр организатора отменил совместный проект":"Мэр организатора подтвердил совместный результат");})));}
    public synchronized CompletionStage<Void> closeAsync(){if(stopped!=null)return stopped;List<CompletableFuture<?>> accepted;try(var guard=SuiteState.guard()){closed=true;auditTask.cancel();owners.forEach(f->f.completeExceptionally(new IllegalStateException("Раздел остановлен; квитанции сохранены")));var pending=new ArrayList<CompletableFuture<?>>(active.values());pending.add(goods.closeAsync().toCompletableFuture());accepted=List.copyOf(pending);}stopped=CompletableFuture.allOf(accepted.toArray(CompletableFuture[]::new)).handle((v,e)->null).thenCompose(v->audit.closeAsync()).handle((v,auditFailure)->repo.closeAsync().handle((ignored,dbFailure)->{if(auditFailure!=null)throw new CompletionException(auditFailure);if(dbFailure!=null)throw new CompletionException(dbFailure);return (Void)null;})).thenCompose(stage->stage).toCompletableFuture();return stopped;}
}
